function shouldFire(now, zone, cronRule) {
  const local = toZoneDate(now, zone);
  const [hour, minute] = cronRule.split(' ');
  return local.hour === parseInt(hour) && local.minute === parseInt(minute);
}

function generateIdempotencyKey(userId, scheduledTime) {
  return `${userId}:${scheduledTime.toISOString()}`;
}

function calculateBackoff(attempt) {
  return Math.min(1000 * Math.pow(2, attempt), 30000);
}
